async function listConferences(userId,kind){if(conferenceRepo.enabled)return conferenceRepo.listForUser(userId,kind);return store.data.conferenceRooms.filter(r=>r.kind===kind&&(store.data.conferenceMembers.some(m=>m.roomId===r.id&&m.userId===userId)||store.data.conferenceInvites.some(i=>i.roomId===r.id&&i.invitedUserId===userId&&i.status==='pending'))).map(r=>({...r,role:store.data.conferenceMembers.find(m=>m.roomId===r.id&&m.userId===userId)?.role||null,memberCount:store.data.conferenceMembers.filter(m=>m.roomId===r.id).length,inviteId:store.data.conferenceInvites.find(i=>i.roomId===r.id&&i.invitedUserId===userId&&i.status==='pending')?.id||null}))}
async function createConference(data){if(conferenceRepo.enabled)return conferenceRepo.create(data);const room={id:data.id,ownerId:data.ownerId,kind:data.kind,title:data.title,description:data.description,syloraEnabled:false,status:'open',createdAt:data.createdAt};store.data.conferenceRooms.push(room);store.data.conferenceMembers.push({roomId:room.id,userId:data.ownerId,role:'owner',joinedAt:data.createdAt});store.save();return{...room,role:'owner',memberCount:1}}
async function inviteConference({id,roomId,ownerId,username,createdAt}){if(conferenceRepo.enabled)return conferenceRepo.invite({id,roomId,ownerId,username,createdAt});const room=store.data.conferenceRooms.find(r=>r.id===roomId&&r.ownerId===ownerId);if(!room)return undefined;const target=store.data.users.find(u=>u.username.toLowerCase()===username.toLowerCase());if(!target)return null;if(target.id===ownerId)return undefined;let invite=store.data.conferenceInvites.find(i=>i.roomId===roomId&&i.invitedUserId===target.id);if(invite){invite.status='pending';invite.createdAt=createdAt}else{invite={id,roomId,invitedUserId:target.id,invitedBy:ownerId,status:'pending',createdAt};store.data.conferenceInvites.push(invite)}store.save();return{id:invite.id,user:store.publicUser(target)}}
async function acceptConference(inviteId,userId){if(conferenceRepo.enabled)return conferenceRepo.accept({inviteId,userId,joinedAt:store.now()});const invite=store.data.conferenceInvites.find(i=>i.id===inviteId&&i.invitedUserId===userId&&i.status==='pending');if(!invite)return null;invite.status='accepted';if(!store.data.conferenceMembers.some(m=>m.roomId===invite.roomId&&m.userId===userId))store.data.conferenceMembers.push({roomId:invite.roomId,userId,role:'member',joinedAt:store.now()});store.save();return{roomId:invite.roomId}}
