function staticFile(req, res, url) {
  let file = url.pathname === '/' ? '/index.html' : url.pathname;
  const resolved = path.resolve(publicDir, `.${file}`);
  if (!resolved.startsWith(publicDir) || !fs.existsSync(resolved) || fs.statSync(resolved).isDirectory()) { res.writeHead(404); return res.end('Not found'); }
  const ext = path.extname(resolved); const types = { '.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'text/javascript; charset=utf-8','.svg':'image/svg+xml' };
  res.writeHead(200, { 'content-type': types[ext] || 'application/octet-stream' }); fs.createReadStream(resolved).pipe(res);
}

export const server = http.createServer(async (req, res) => {
  try { securityHeaders(res); const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`); const mediaMatch=route('/media/:id',url.pathname); if(mediaMatch&&req.method==='GET')return serveMedia(req,res,mediaMatch.id);const hlsMatch=route('/hls/:mediaId/:file',url.pathname);if(hlsMatch&&req.method==='GET')return serveHls(req,res,hlsMatch.mediaId,hlsMatch.file); if (url.pathname.startsWith('/api/')) { if (!await allowRequest(req)) return json(res,429,{error:'RATE_LIMITED'}); await api(req,res,url); } else staticFile(req,res,url); }
  catch (e) { console.error(e); if (!res.headersSent) json(res, e.message === 'BODY_TOO_LARGE' ? 413 : 400, { error: e.message || 'BAD_REQUEST' }); else res.end(); }
});

if (process.env.NODE_ENV !== 'test') {
  Promise.allSettled([liveFanout.start(),conferenceFanout.start(),realtimeFanout.start()]).then(()=>realtimeOutbox.start());
  server.listen(port, () => console.log(`SYLORA running on http://localhost:${port}`));
  const shutdown=async()=>{server.close();realtimeOutbox.stop();await Promise.allSettled([liveFanout.close(),conferenceFanout.close(),realtimeFanout.close()]);await Promise.allSettled([postgres.close(),redis.close()]);process.exit(0)};
  process.once('SIGTERM',shutdown);process.once('SIGINT',shutdown);
}
